1	/* ============================================================
2	   PortfolioGrid — matches Webflow our-works.html exactly
3	   Live site: container 1300px, grid 305px+975px, cards 480x470
4	   ============================================================ */
5	
6	.section {
7	  background-color: transparent;
8	  padding: 0 3% 60px;
9	  display: block;
10	  position: relative;
11	}
12	
13	.container {
14	  max-width: 1300px;
15	  margin-left: auto;
16	  margin-right: auto;
17	}
18	
19	/* ---------- Filter header bar (search + tags) ---------- */
20	/* Live: grid-template-columns: 305px 955px 0px — sort is hidden */
21	/* Live: no visible border, padding .5rem 0 2rem, 3-col grid with sort at 0px */
22	.filterHeader {
23	  grid-column-gap: 20px;
24	  grid-row-gap: 20px;
25	  background-color: transparent;
26	  border: none;
27	  border-radius: 10px;
28	  display: grid;
29	  grid-template-columns: minmax(260px, 260px) 1fr;
30	  align-items: center;
31	  min-height: 4.5rem;
32	  padding: 0.5rem 0 2rem;
33	}
34	
35	/* Live: font-size 1rem, padding 1rem 1.5rem 1rem 1rem */
36	.searchField {
37	  font-family: 'Roobert PRO', Arial, sans-serif;
38	  font-size: 1rem;
39	  color: #2b2b2b;
40	  width: 100%;
41	  min-height: 45px;
42	  padding: 1rem 1.5rem 1rem 1rem;
43	  border: 1px solid rgba(33, 207, 255, 0.23);
44	  border-radius: 10px;
45	  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
46	  outline: none;
47	  background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 24 24' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='11' cy='11' r='8' stroke='%236b7280' stroke-width='2'/%3E%3Cline x1='21' y1='21' x2='16.65' y2='16.65' stroke='%236b7280' stroke-width='2' stroke-linecap='round'/%3E%3C/svg%3E");
48	  background-repeat: no-repeat;
49	  background-position: 94% center;
50	  background-size: 1.5rem;
51	  transition: border-color 0.15s ease;
52	}
53	
54	.searchField::placeholder { color: #9ca3af; }
55	.searchField:focus { border-color: #21cfff; }
56	.searchField::-webkit-search-cancel-button { display: none; }
57	
58	/* Filter tags area */
59	.tagsArea {
60	  display: flex;
61	  flex-wrap: wrap;
62	  gap: 8px;
63	  align-items: center;
64	}
65	
66	.tagsLabel {
67	  font-family: 'Roobert PRO', Arial, sans-serif;
68	  font-size: 13px;
69	  color: #6b7280;
70	  margin: 0;
71	}
72	
73	.activeTag {
74	  display: inline-flex;
75	  align-items: center;
76	  background-color: #082753;
77	  color: #fff;
78	  font-family: 'Roobert PRO', Arial, sans-serif;
79	  font-size: 0.85rem;
80	  font-weight: 500;
81	  padding: 0.5rem 2.5rem 0.5rem 1rem;
82	  border-radius: 10px;
83	  position: relative;
84	  margin: 0.5rem 0.5rem 0.5rem 0;
85	}
86	
87	.activeTagClose {
88	  position: absolute;
89	  right: 8px;
90	  top: 50%;
91	  transform: translateY(-50%);
92	  background: none;
93	  border: none;
94	  color: #fff;
95	  cursor: pointer;
96	  padding: 0;
