3	import { useEffect, useCallback } from "react";
4	import Image from "next/image";
5	import type { PortfolioItem } from "@/types/portfolio";
6	import styles from "./portfolio-popup.module.css";
7	
8	interface PortfolioPopupProps {
9	  item: PortfolioItem;
10	  onClose: () => void;
11	}
12	
13	export function PortfolioPopup({ item, onClose }: PortfolioPopupProps) {
14	  const handleKeyDown = useCallback(
15	    (e: KeyboardEvent) => {
16	      if (e.key === "Escape") onClose();
17	    },
18	    [onClose]
19	  );
20	
21	  useEffect(() => {
22	    document.addEventListener("keydown", handleKeyDown);
23	    document.body.style.overflow = "hidden";
24	
25	    return () => {
26	      document.removeEventListener("keydown", handleKeyDown);
27	      document.body.style.overflow = "";
28	    };
29	  }, [handleKeyDown]);
30	
31	  // Full content mode for items with detail pages, gallery/image mode for others
32	  const isFullMode = item.hasDetailPage;
33	  const containerClass = isFullMode
34	    ? styles.container
35	    : `${styles.container} ${styles.containerGallery}`;
36	
37	  return (
38	    <div
39	      className={styles.overlay}
40	      onClick={(e) => {
41	        if (e.target === e.currentTarget) onClose();
42	      }}
43	      role="dialog"
44	      aria-modal="true"
45	      aria-label={`${item.name} project details`}
46	    >
47	      <div className={containerClass}>
48	        <button
49	          type="button"
50	          className={styles.closeBtn}
51	          onClick={onClose}
52	          aria-label="Close popup"
53	        >
54	          &times;
55	        </button>
56	
57	        {isFullMode ? (
58	          <iframe
59	            src={`/our-works/${item.slug}`}
60	            className={styles.iframe}
61	            title={`${item.name} project details`}
62	            allowFullScreen
63	          />
64	        ) : (
65	          <div className={styles.galleryContent}>
66	            <div className={styles.galleryImageWrap}>
67	              <Image
68	                src={item.featuredImage}
69	                alt={`${item.name} — Boldteq portfolio project`}
70	                fill
71	                sizes="(max-width: 600px) 90vw, 560px"
72	                className={styles.galleryImage}
73	                priority
74	              />
75	            </div>
76	            <div className={styles.galleryInfo}>
77	              <h2 className={styles.galleryTitle}>{item.name}</h2>
78	              <span className={styles.galleryBadge}>{item.category}</span>
79	            </div>
80	          </div>
81	        )}
82	      </div>
83	    </div>
84	  );
85	}
